// src/api/adminApi.js
import API from './axios';

// Fetch users with optional search/filter
export const fetchUsers = (search = '') => {
  return API.get(`/admin/users?search=${search}`);
};

// Toggle user/seller status (Active <-> Blocked)
export const toggleUserStatus = (customId) => {
  return API.patch(`/admin/users/${customId}/toggle-status`);
};
